ALTER TABLE public.places
  DROP CONSTRAINT IF EXISTS places_category_check;

ALTER TABLE public.places
  ADD CONSTRAINT places_category_check
  CHECK (
    category IN (
      'Historical', 'Culture', 'Nature', 'Food', 'Cafe', 'Shopping',
      'Mosques', 'Churches', 'Streets'
    )
  );

INSERT INTO public.places (
  id, name, name_en, name_ar, description, description_en, description_ar,
  image_url, image_urls, rating, category, category_ar, lat, lng, address,
  address_ar, open_hours, review_count, price_level, governorate, display_order
)
